resource_table=table(['项目','实测'],[['CPU / 内存',f"{e(machine['cpu'])} / {machine['physical_cores']} 核 / {machine['memory_bytes']/2**30:.0f} GiB"],['主计算进程墙钟时间',f"{resources['elapsed_seconds']:.2f} 秒"],['其中：虚拟肽枚举、排序与结果落盘',f"{timing['virtual_digestion_and_holdout_validation']:.2f} 秒"],['其中：模型加载',f"{timing['model_load']:.2f} 秒"],['其中：功能推理与保存',f"{timing['functional_inference_and_storage']:.2f} 秒"],['其中：实验关联分析',f"{timing['bulk_experimental_validation']:.2f} 秒"],['独立复核进程',f"{read('audit-compute/resources.json')['elapsed_seconds']:.2f} 秒"],['主进程树峰值 RSS（每秒采样）',f"{resources['process_tree_peak_RSS_bytes']/2**30:.2f} GiB"],['系统最低可用内存',f"{resources['system_min_available_bytes']/2**30:.2f} GiB"],['监测期间 swap 占用峰值',f"{resources['swap_peak_used_bytes']/2**30:.2f} GiB"],['主进程树累计 CPU 时间',f"{resources['sampled_tree_CPU_seconds']:.2f} CPU 秒"]])
